def main():
    print("Welcome to Mystery Box!")
    print("You have 5 attempts to guess the 3-digit code.")
    code = generate_code()
    attempts = 5
    while attempts > 0:
        guess = get_guess()
        if guess == code:
            print("Congratulations! You cracked the code!")
            break
        else:
            print("Too low" if guess < code else "Too high")
            attempts -= 1
    else:
        print(f"Game over! The code was {code}.")

if __name__ == "__main__":
    main()
